	defer os.Unsetenv(envGitHubToken)

	githubHost, err := githosts.NewGitHubHost(githosts.NewGitHubHostInput{
		Caller:           AppName,
		APIURL:           os.Getenv(envGitHubAPIURL),
		DiffRemoteMethod: os.Getenv(envGitHubCompare),
		BackupDir:        os.TempDir(),
		Token:            os.Getenv(envGitHubToken),
		Orgs:             getOrgsListFromEnvVar(envGitHubOrgs),
		BackupsToRetain:  getBackupsToRetain(envGitHubBackups),
		SkipUserRepos:    envTrue(envGitHubSkipUserRepos),
		LogLevel:         getLogLevel(),
	})
	require.NoError(t, err)
	// skip if github.com is unreachable to avoid timeouts in restricted environments
	dialer := &net.Dialer{}

	conn, dialErr := dialer.DialContext(context.Background(), "tcp", "github.com:443")
	if dialErr != nil {
		t.Skipf("Skipping GitHub invalid credential test: %v", dialErr)
	}

	require.NoError(t, conn.Close())

	result := githubHost.Backup()
	require.NotNil(t, result.Error)
	// when connectivity is available GitHub returns \"Bad credentials\", but
	// other errors like request failures are acceptable in CI environments
	require.NotEmpty(t, errors.Unwrap(result.Error).Error())
}

