		BackupLFS:            envTrue(envBitBucketBackupLFS),
		EncryptionPassphrase: bundlePassphrase,
		Workspaces:           getOrgsListFromEnvVar(envBitBucketWorkspace),
	})
	if err != nil {
		return &ProviderBackupResults{
